 VALUES ('MDB:root:بين:derivations', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'derivations', NULL, 3, 'الاشتقاق', 'Derived Family', 'اشتقاق', 'جذرٌ واحد بأبنية شتّى؛ كلُّ مشتقٍّ هو الأصل نفسه ==(الانفصال ← الوضوح)== منكسرًا في وزن. هذه أبنية الجذر في القرآن.', 'One root, many builds — every derivation is the same core ==(separation → clarity)== refracted through a pattern. These are the shapes the root ب ي ن actually takes in the Qurʾān.', '',
  '{"groups":[{"form_ar":"الفعل — Verb","items":[{"ar":"بانَ","en":"became clear (I)"},{"ar":"بَيَّنَ","en":"made clear (II)"},{"ar":"تَبَيَّنَ","en":"became distinct (V)"},{"ar":"أبانَ","en":"clarified (IV)"},{"ar":"اسْتَبانَ","en":"sought clarity (X)"}]},{"form_ar":"اسم الفاعل — Active ptcp.","items":[{"ar":"مُبِين","en":"clear / clarifying"},{"ar":"مُبَيِّن","en":"one who makes clear"},{"ar":"مُسْتَبِين","en":"becoming manifest"}]},{"form_ar":"المصدر — Verbal noun","items":[{"ar":"بَيَان","en":"clear exposition"},{"ar":"تِبْيَان","en":"full clarification"}]},{"form_ar":"الصفة / الاسم — Adj. & noun","items":[{"ar":"بَيِّنَة","en":"clear proof"},{"ar":"مُبَيِّنَة","en":"manifest (fem.)"},{"ar":"بَيْن","en":"the interval between"}]}]}', 'kmaps_five_lens', 1, 'quran', '["quran","classical"]', NULL, NULL, NULL, '{"icon":"git-fork"}', 'live');
