 VALUES ('MDB:root:بين:lexicon', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'lexicon', NULL, 4, 'المعاجم', 'Classical Lexicons', 'لغت', 'الظلال التي يضيفها كلُّ معجميّ.', '==The shade each lexicographer adds== — not raw entries.', '',
  '{"entries":[{"source":"Maqāyīs al-Lugha","death":"d. 395 AH","shade_ar":"بُعْدُ الشيء وانكشافُه — أصلٌ واحد","shade_en":"One core: parting and disclosure. البَيْن is separation; بانَ وأبانَ is to become clear."},{"source":"al-Rāghib, Mufradāt","death":"d. 502 AH","shade_ar":"بانَ = انفصلَ وظهرَ ما كان مستترًا","shade_en":"بَيْن names the interval between two things; بانَ = separated AND manifested what was hidden — each half usable alone (بانَ الصُّبح, the dawn showed)."},{"source":"Sinai, Key Terms","death":"contemp.","shade_ar":"بَيان · مُبَيِّن · مُسْتَبِين","shade_en":"Groups the root''s Qurʾānic key-terms of clarity/exposition: بيان, مُبيِّن, مُستبين."}]}', 'kmaps_five_lens', 1, 'classical', '["classical"]', NULL, NULL, NULL, '{"icon":"book-open"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
