 VALUES ('MDB:root:بين:attestations', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'attestations', NULL, 5, 'الاستعمال الأقدم', 'Earliest Usage', 'قدیم ترین استعمال', 'قبل أن يصير وصفًا للوحي، عاش الجذر «ب ي ن» في الصحراء والخيمة. أقدمُ استعمالاته حسّيٌّ واجتماعيّ — فِراقٌ، وفجرٌ، وظعائنُ ترحل، وبيانُ خطيبٍ — وكلٌّ منها يترك صورةً لا يفارقها المعنى المتأخّر.', 'Before it was ever an epithet of revelation, ب ي ن lived in the desert and the tent. Its oldest attested uses are ==physical and social== — parting, dawn, the pulling-away of a caravan, the plain speech of an orator — and each leaves a picture the later meaning never sheds.', '',
  '{"witnesses":[{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"البَيْن · الفِراق","phrase_ar":"غُرابُ البَيْن","gloss_en":"“the crow of parting” — a fixed idiom: the raven whose cawing over an abandoned camp was read as the omen that the tribe, and the beloved, would depart.","image_ar":"غرابٌ أسود ينعق فوق ديارٍ خاوية","image_en":"a black crow over an emptied campsite — separation announced","lex_source":"ابن فارس · مقاييس اللغة","lex_ar":"البَيْنُ هو الانفصال","lex_en":"al-bayn = the separation itself (d. 395 AH)","motif":"parting","icon":"sunrise"},{"era_ar":"مَثَلٌ سائر","era_en":"Proverb","kind_ar":"بانَ · ظَهَر","phrase_ar":"قد بانَ الصُّبْحُ لِذي عَيْنَيْن","gloss_en":"“the dawn has shown itself to anyone with eyes” — the proverb for a truth now beyond any denial; what parts from the dark becomes plain to all.","image_ar":"فجرٌ ينفصل عن الليل فيراه كلُّ ذي بصر","image_en":"dawn splitting off from night, plain to every eye","lex_source":"الرّاغب · المفردات","lex_ar":"بانَ الصُّبحُ: ظهرَ ما كان مُستترًا","lex_en":"al-Rāghib''s own shāhid: bāna l-ṣubḥ — the dawn showed (d. 502 AH)","motif":"arrival","icon":"star"},{"era_ar":"النَّسيب","era_en":"Ode-opening","kind_ar":"بانَ الخَليط · المسافة","phrase_ar":"بانَ الخَليطُ ولم يَأْذَنوا برَحيلِهِمِ","gloss_en":"“the companions parted and gave no warning of leaving” — the ode''s classic opening formula: the mingled camp pulls away across the sand and the interval (بَيْن) between lovers opens.","image_ar":"ظَعائنُ ترحل والغبارُ يفصل بين الأحبّة","image_en":"a caravan pulling away, dust widening the gap between lovers","lex_source":"الرّاغب · المفردات","lex_ar":"البَيْن: الفَصلُ بين الشيئين","lex_en":"al-bayn = the interval between two things (d. 502 AH)","motif":"split","icon":"split"},{"era_ar":"الخَطابة","era_en":"Oratory","kind_ar":"البَيان · الفصاحة","phrase_ar":"أوتِيَ بَيانًا","gloss_en":"“he was granted bayān” — clear, distinct speech that sets each meaning apart from the next; the most prized virtue of the pre-Islamic orator.","image_ar":"لسانٌ يفصل المعاني فتقفُ كلٌّ على حِدَة","image_en":"a tongue that separates meanings so each stands on its own","lex_source":"الرّاغب · سِنائي","lex_ar":"بَيان · مُبَيِّن · مُستَبِين","lex_en":"the root''s clarity-cluster — Rāghib & Sinai","motif":"family","icon":"git-fork"}]}', 'kmaps_five_lens', 0, 'classical', '["classical"]', NULL, NULL, NULL, '{"icon":"landmark"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
