 VALUES ('MDB:root:بين:synthesis', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'synthesis', NULL, 6, 'التخليص الجامع', 'Synthesis', '', 'أربعةُ مصادرَ وقراءةٌ واحدة: المعاجمُ تُعطي الصورة، وسِنائي يُسمّي ألفاظَ الوضوح القرآنية، والتركيبُ الاصطلاحيّ يكشف نحوَ الجذر، والمفسّرون يُطبّقونه — وكلُّها تقول شيئًا واحدًا: المُبِينُ انفصالٌ صار مرئيًّا، والوحيُ أعلى حالاته.', 'Four sources, one reading. The lexicons give the picture, Sinai names the Qurʾānic clarity-vocabulary, the verbal idiom shows the syntax the root prefers, and the mufassirūn apply it — together they say one thing: مُبِين is ==separation made visible, and revelation== is its highest case.', '',
  '{"strands":[{"kind":"lexicon","badge":"المعجم","source":"ابن فارس · الرَّاغب","ar":"بُعْدٌ وانكشاف؛ فصلٌ ثمّ ظهور","en":"A single core of parting + disclosure — what separates then shows itself.","concept":"parting → disclosure","icon":"book-open"},{"kind":"sinai","badge":"Key Terms · Sinai","source":"Sinai, Key Terms of the Qurʾān","ar":"بيان · مُبيِّن · مُستبين","en":"The root’s Qurʾānic clarity-cluster: exposition (بيان), one-who-clarifies (مُبيِّن), becoming-manifest (مُستبين).","concept":"the clarity vocabulary","icon":"key-round"},{"kind":"verbal_idiom","badge":"التركيب","source":"المدوّنة · ٢:٢٥٦","ar":"تَبَيَّنَ … مِنْ — «قد تبيّن الرشدُ من الغيّ»","en":"The root’s signature construction: X becomes distinct FROM Y — guidance from error (2:256). Clarity is always clarity-apart-from-something.","concept":"distinct-from-something","icon":"link"},{"kind":"tafsir","badge":"التفسير","source":"الطبري · ابن عاشور","ar":"يُبيّن ما يحتاجه الناس؛ بيِّنٌ ومُبيِّنٌ معًا","en":"Ṭabarī: it makes plain the guidance and rulings people need. Ibn ʿĀshūr: manifest in itself and clarifying at once.","concept":"clear + clarifying","icon":"library"}],"output":"separation made visible"}', 'kmaps_synthesis', 1, 'quran', '["quran","classical","msa"]', 'kmaps-media/roots/byn/synthesis-weave.svg', 'image', 'four source-strands (lexicon · Sinai · idiom · tafsīr) weaving into one reading', '{"icon":"waypoints"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:root:بين:metaphor', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'metaphor', NULL, 7, 'التصوير الذهني', 'Conceptual Metaphor', 'تصور', 'الفهمُ أن ترى الشيء يخرج من خلفيّته فيتميّز. الصورةُ الحسّيّة للجذر — طريقٌ يشقّ الأرض، وصبحٌ ينفصل عن الليل (بانَ الصبح) — تُحمَل كما هي إلى المعنى المجرّد: فالكتاب المبين قد بانت حقائقُه من الالتباس فصارت ظاهرة.', 'To understand is to see something step out of a background and stand apart. The root''s physical picture — a road parting the land, dawn breaking off from night (بانَ الصُّبح) — is carried whole into the abstract: a clear Book is one whose truths have ==separated out from confusion== and now stand visible.', '',
  '{"source_ar":"الانفصال الحسّي","target_ar":"الوضوح الذهني","mapping":"CLARITY IS SEPARATION"}', 'kmaps_five_lens', 1, 'classical', '["classical","quran"]', 'kmaps-media/roots/byn/metaphor-dawn.webp', 'image', 'CLARITY IS SEPARATION — dawn separating from night as a thing becoming visible', '{"icon":"eye"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:root:بين:kindred', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'kindred', NULL, 8, 'النظائر والأضداد', 'Kindred & Contrast', 'نظائر و اضداد', 'موقع «مبين» بين نظائره في الوضوح.', 'Where مُبِين sits among its ==neighbours of clarity==.', '',
  '{"synonyms":[{"ar":"ظاهر","en":"ẓāhir","note":"outwardly evident — surface visibility, not clarity by separation."},{"ar":"واضح","en":"wāḍiḥ","note":"clear/plain (MSA default) — result-focused, lacks the causative half."},{"ar":"جَلِيّ","en":"jaliyy","note":"polished-bright, unmistakable — intensity of clearness."}],"contrast":[{"ar":"مُبْهَم","en":"mubham","note":"vague, unseparated — the exact opposite: nothing stands apart."},{"ar":"خَفِيّ","en":"khafiyy","note":"hidden, still merged with its background."}]}', 'kmaps_five_lens', 1, 'classical', '["classical","msa"]', NULL, NULL, NULL, '{"icon":"git-compare"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:root:بين:constellation', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'constellation', NULL, 9, 'كوكبة الكلمة', 'Word Constellation', 'كلمے كا جھرمٹ', 'الجذر كلُّه في نظرة. «مُبِين» في المركز، وتدور حوله مشتقّاتُه أقربَ (ذهبيّ)، ثمّ نظائرُ الوضوح أبعدَ (أزرق)، وأضدادُه — المُبْهَم والخَفِيّ — على الطرف (أحمر).', '==The whole root at a glance.== مُبِين sits at the centre; its own derivations orbit closest (gold), the near-synonyms of clarity sit further out (blue), and its opposites — the un-separated, the still-hidden — mark the far edge (red).', '',
  '{"center":{"ar":"مُبِين","root":"ب ي ن"},"nodes":[{"ar":"بَيان","en":"exposition","ring":1,"angle":0,"kind":"derived"},{"ar":"بَيَّنَ","en":"made clear","ring":1,"angle":60,"kind":"derived"},{"ar":"أبانَ","en":"clarified","ring":1,"angle":120,"kind":"derived"},{"ar":"بَيِّنة","en":"clear proof","ring":1,"angle":180,"kind":"derived"},{"ar":"تِبْيان","en":"full clarifying","ring":1,"angle":240,"kind":"derived"},{"ar":"بانَ","en":"became clear","ring":1,"angle":300,"kind":"derived"},{"ar":"واضح","en":"plain","ring":2,"angle":30,"kind":"synonym"},{"ar":"ظاهر","en":"evident","ring":2,"angle":90,"kind":"synonym"},{"ar":"جَلِيّ","en":"unmistakable","ring":2,"angle":150,"kind":"synonym"},{"ar":"مُبْهَم","en":"vague","ring":2,"angle":210,"kind":"contrast"},{"ar":"خَفِيّ","en":"hidden","ring":2,"angle":270,"kind":"contrast"}]}', 'kmaps_five_lens', 1, 'quran', '["quran","classical","msa"]', NULL, NULL, NULL, '{"icon":"orbit"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:root:بين:occurrences', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'occurrences', NULL, 10, 'الشواهد القرآنية', 'Qurʾānic Occurrences', 'شواہد', 'ليست تكرارَ افتتاح «كتاب مبين»، بل ما يصفه «مبين» من موصوفاتٍ مختلفة في القرآن — كلُّ موصوفٍ يُنزِل الأصلَ ==(الانفصال ← الوضوح)== منزلةً جديدة.', 'Not the repeated كتاب-مبين opening, but the distinct things مُبِين describes across the Qurʾān — each noun bends the same core ==(separation → clarity)== a different way.', '',
  '{"items":[{"ayah_key":"44:2","kind_ar":"الكتاب","en":"the Book","motif":"arrival","text_ar":"وَالْكِتَابِ الْمُبِينِ","note":"Book — clear in itself and clarifying: the study locus.","focus":true,"icon":"star"},{"ayah_key":"26:195","kind_ar":"اللسان","en":"the tongue","motif":"family","text_ar":"بِلِسَانٍ عَرَبِيٍّ مُبِينٍ","note":"Tongue — a clear Arabic speech; clarity as intelligible language.","icon":"git-fork"},{"ayah_key":"36:12","kind_ar":"السِّجِلّ","en":"the record","motif":"shape","text_ar":"أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ","note":"Record — a register that lays every deed out plainly; eschatological ledger.","icon":"layout-grid"},{"ayah_key":"2:168","kind_ar":"العداوة","en":"the enemy","motif":"split","text_ar":"إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ","note":"Enemy — Satan as an open, declared foe; clarity as being out in the open.","icon":"split"},{"ayah_key":"16:35","kind_ar":"التبليغ","en":"the conveyance","motif":"parting","text_ar":"إِلَّا الْبَلَاغُ الْمُبِينُ","note":"Conveyance — the messengers'' task is only the clear delivery itself.","icon":"sunrise"},{"ayah_key":"5:110","kind_ar":"على ألسنة المنكرين","en":"on deniers’ tongues","motif":"debate","text_ar":"إِنْ هَٰذَا إِلَّا سِحْرٌ مُبِينٌ","note":"Sorcery — مُبِين on the deniers'' tongue: ''plain magic'', clarity turned into accusation.","icon":"scale"},{"ayah_key":"67:26","kind_ar":"الإنذار","en":"the warning","motif":"debate","text_ar":"وَإِنَّمَا أَنَا نَذِيرٌ مُبِينٌ","note":"Warner — the Prophet himself as the one who makes the warning plain.","icon":"scale"}]}', NULL, 0, 'quran', '["quran"]', NULL, NULL, NULL, '{"icon":"list-ordered"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
