 VALUES ('MDB:root:بين:master_story', 'root', 'بين', NULL, 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'master_story', NULL, 13, 'القصة الجامعة', 'Master Story', 'جامع کہانی', 'يبدأ الجذرُ صورةً للانفصال — طريقٌ يشقّ الصحراء، وصبحٌ ينفصل عن الليل. ومن هذا الأصل الواحد «ب ي ن» تنمو أسرةٌ كاملة: البَيْن، وبانَ، وبيَّنَ وأبانَ، والبيان، والبيّنة. كلُّ بناءٍ هو الفكرةُ نفسها: انفصالٌ يُفضي إلى الرؤية. وفي (44:2) يجيء الجذرُ «مبينًا» — اسمَ فاعلٍ من الإفعال على وزن مُفْعِل؛ ولأنّ البابَ لازمٌ ومتعدٍّ، تدّعي الكلمةُ أمرين معًا: الكتابُ بيِّنٌ في نفسه، ومُبيِّنٌ لغيره. ويجعله النحاةُ نعتًا للكتاب مجرورًا في القسم، ويكشف البلاغيّون أنّ القسمَ هو الحجّة: أقسم بالكتاب على الكتاب، وحملت الصفةُ «مبين» البرهان. ومن ثمّ اختلف المترجمون؛ فرأت خريطةُ الاستعمال الشكلَ نفسه: يتجمّع «مبين» في الحقلين الروحيّ والظاهر، ويرقّ نحو التشريعيّ — فهو أقربُ إلى وصف الوحي وهو يخرج من الخفاء ليقفَ في العَراء.', 'begins as a picture of parting — a road cutting the desert, dawn breaking off from night. From that one root, ب ي ن, Arabic grows a whole family: بَيْن (the gap between), بانَ (to show), بيَّنَ and أبانَ (to make show), بيان (clear speech), بيِّنة (a proof that stands out). Every build is the same idea refracted — ==separation that leads to sight==. At 44:2 the root arrives as مُبِين, the active participle of Form IV on the pattern مُفْعِل; because that form is at once intransitive and transitive, the word claims two things in one breath: the Book is clear in itself and it makes all else clear. The grammarians place it as a mere adjective of الكتاب, genitive in the oath — yet the rhetoricians show the oath is the argument: God swears by the Book, about the Book, and the single epithet مُبِين carries the proof. This is why translators split — ''the clear Book'' keeps only half; ''the Book that makes things clear'' recovers the causative that the formula كتاب مبين, echoing across 43:2, 12:1, 26:2, 27:1 and 28:2, is really asserting. Read the usage map and the same shape appears: مُبِين gathers in the spiritual and manifest bands, thinning toward the legal — it is less a word about rules than about revelation stepping out of concealment and standing, at last, in the open.', '',
  '{"medallion_ar":"مُبِين","medallion_root":"ب ي ن","threads":["root DNA","wazn IV","derivations","iʿrāb","lexicons","balāgha","translators","usage map"],"movements":[{"no":"I","motif":"parting","en":"The Picture","ar":"الصورة","accent":"#c9a84c","text":"It begins as a picture of parting — a road cutting the desert, dawn breaking off from night. The root’s oldest sense is a separation that leads to sight: what stands apart becomes visible.","icon":"sunrise"},{"no":"II","motif":"family","en":"The Family","ar":"الأسرة","accent":"#7fb58f","text":"From that one root, ب ي ن, Arabic grows a whole family — every build the same idea refracted through a pattern.","chips":[{"ar":"بَيْن","en":"the gap between"},{"ar":"بانَ","en":"to show"},{"ar":"بيَّنَ","en":"to make clear"},{"ar":"أبانَ","en":"to clarify"},{"ar":"بيان","en":"clear speech"},{"ar":"بيِّنة","en":"a standing proof"}],"icon":"git-fork"},{"no":"III","motif":"arrival","en":"The Arrival","ar":"الورود","accent":"#e8c96a","text":"At 44:2 the root arrives as مُبِين — the active participle of Form IV on the pattern مُفْعِل. Because that form is at once intransitive and transitive, the word claims two things in one breath: the Book is clear in itself, and it makes all else clear.","icon":"star"},{"no":"IV","motif":"debate","en":"The Argument","ar":"الحجّة","accent":"#93b8d6","text":"The grammarians place it as a mere adjective of الكتاب, genitive in the oath. Yet the rhetoricians show the oath itself IS the argument: God swears by the Book, about the Book — and the single epithet مُبِين carries the whole proof.","icon":"scale"},{"no":"V","motif":"split","en":"The Split","ar":"الترجمة","accent":"#b3a6f6","text":"This is why translators split. “The clear Book” keeps only half; “the Book that makes things clear” recovers the causative — the claim the formula كتاب مبين is really making, echoing across 43:2, 12:1, 26:2, 27:1 and 28:2.","icon":"split"},{"no":"VI","motif":"shape","en":"The Shape","ar":"الخريطة","accent":"#c9a84c","text":"Read the usage map and the same shape appears: مُبِين gathers in the spiritual and manifest bands, thinning toward the legal. It is less a word about rules than about revelation stepping out of concealment — standing, at last, in the open.","icon":"layout-grid"}]}', 'kmaps_master_story', 1, 'quran', '["quran","classical","msa"]', 'kmaps-media/roots/byn/master-story.mp4', 'image', 'animated arc: parting → manifestation → the Book that clarifies', '{"icon":"sparkles"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:ctx:بين:44:2:irab', 'context', '44:2', '44:2:2', 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'irab', NULL, 1, 'الإعراب', 'Iʿrāb in Context', 'اعراب', 'مجرور وعلامته الكسرة، وهو نعتٌ للكتاب في القسم «وَالْكِتَابِ الْمُبِينِ»: قال الميسّر الواو واو القسم، والكتاب مجرور بها، والمبين نعتٌ له. ولا خلاف في هذا الموضع.', '==Genitive (مجرور)== with kasra, functioning as نعت (adjective) of الكتاب inside the oath وَالكتابِ المُبِين: al-Muyassar reads the wāw as wāw al-qasam, الكتاب genitive by it (governed by an elided أُقسِمُ), and المُبِين its adjective. No dispute is recorded for this position in the iʿrāb works consulted.', '',
  '{"role_ar":"نعت","role_en":"adjective","position_ar":"مجرور","sign_ar":"الكسرة","sources":["al-Muyassar 44:2","Iʿrāb al-Qurʾān"]}', 'muyassar_irab', 0, 'quran', '["quran"]', NULL, NULL, NULL, '{"icon":"tag"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:ctx:بين:44:2:balagha', 'context', '44:2', '44:2:2', 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'balagha', NULL, 2, 'البلاغة', 'Balāgha', 'بلاغہ', 'قسمٌ بالكتاب على الكتاب: المُقسَمُ به هو نفسُه دليلُ المُقسَمِ عليه (إنّا أنزلناه). وصفةٌ واحدة «مبين» تحمل الحجّة — وصفٌ من الإفعال يجمع دعويين: بيِّنٌ في نفسه، مُبيِّنٌ لغيره.', 'The oath swears BY the Book about the Book: the المُقسَم به is itself the proof of the المُقسَم عليه (إنّا أنزلناه, 44:3). Its single epithet مُبِين does the argumentative work — a Form IV participle ==compressing two claims at once==: the Book is clear in itself and gives clarity about everything else.', '',
  '{"formula_ar":"كِتَاب + مُبِين","formula_en":"the كتاب-مبين formula binds revelation to intelligibility","refs":["43:2","12:1","26:2","27:1","28:2"]}', 'kmaps_five_lens', 1, 'quran', '["quran"]', NULL, NULL, NULL, '{"icon":"feather"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:ctx:بين:44:2:translators', 'context', '44:2', '44:2:2', 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'translators', NULL, 3, 'الترجمة', 'Translator Choices', 'ترجمہ', 'لأنّ أبانَ لازمٌ ومتعدٍّ، فالمبين بيِّنٌ ومُبيِّنٌ معًا. وأكثر التراجم تُبقي النصفَ اللازم فقط، والمفقود هو المعنى المتعدّي الذي يدّعيه تركيبُ «كتاب مبين».', 'Because أبانَ is both intransitive and transitive, مُبِين is simultaneously بيِّن (clear) and مُبيِّن (clarity-giving). Most renderings keep only the intransitive half; the causative force that the formula كتاب مبين is claiming is ==the controlled loss==.', '',
  '{"renderings":[{"translator":"Abdel Haleem","text":"the Scripture that makes things clear","reading":"causative"},{"translator":"Pickthall","text":"the Scripture that maketh plain","reading":"causative"},{"translator":"Yusuf Ali","text":"the Book that makes things clear","reading":"causative"},{"translator":"Sahih International","text":"the clear Book","reading":"partial"},{"translator":"K-MAPS gloss","text":"the Book — clear in itself and clarifying","reading":"both"}]}', 'kmaps_five_lens', 1, 'quran', '["quran","msa"]', NULL, NULL, NULL, '{"icon":"languages"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur, text_ar, text_en, text_ur,
  data_json, source_slug, is_synthesis, register, registers_json, media_r2_key, media_kind, media_alt, meta_json, status)
 VALUES ('MDB:ctx:بين:44:2:tafsir', 'context', '44:2', '44:2:2', 44, 2, 2, '44:2', 'بين', 'مُبِين',
  'tafsir', NULL, 4, 'التفسير والعلماء', 'Tafsīr & Scholars', 'تفسیر', '', '', '',
  '{"entries":[{"scholar":"al-Ṭabarī","work":"Jāmiʿ al-Bayān","text":"al-Ṭabarī reads مُبِين for what the Book does: it lays everything out plainly — the guidance to follow, the rulings to live by, and where the lawful ends and the unlawful begins — so that truth stands apart from falsehood for anyone who reflects on it."},{"scholar":"al-Zamakhsharī","work":"al-Kashshāf","text":"al-Zamakhsharī notes that مُبِين can be read two ways, since the verb behind it works both ways. Either the Book makes the truth clear to us — setting out right guidance and the sacred law — or the Book is clear in and of itself: plainly a miracle that no one can imitate."},{"scholar":"Ibn ʿĀshūr","work":"al-Taḥrīr wa-l-Tanwīr","text":"Ibn ʿĀshūr holds that مُبِين carries both senses on purpose, at the same time: the Book is clear in itself, and it makes its meaning clear to others. That double clarity is just what makes it worthy to be sworn by — the oath draws its force from it."}]}', 'TABARI', 0, 'classical', '["classical"]', NULL, NULL, NULL, '{"icon":"library"}', 'live');
INSERT INTO qr_morph_display_blocks
 (id, scope_level, scope_key, word_occ_ref, surah_no, ayah_no, word_index, ayah_key, root_ar, lemma_ar,
